    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        diagonals = {}

        # Collect values for each diagonal
        # Diagonal is identified by d = i - j
        for i in range(n):
            for j in range(n):
                d = i - j
                if d not in diagonals:
                    diagonals[d] = []
                diagonals[d].append(grid[i][j])

        # Sort diagonals based on the rule
        for d in diagonals:
            if d >= 0:
                # Bottom-left (including main diagonal): non-increasing
                diagonals[d].sort(reverse=True)
            else:
                # Top-right: non-decreasing
                diagonals[d].sort(reverse=False)

        # Create result matrix
        result = [[0] * n for _ in range(n)]

        # Fill result matrix
        # We need to track the index for each diagonal
        indices = {d: 0 for d in diagonals}

        for i in range(n):
            for j in range(n):
                d = i - j
                result[i][j] = diagonals[d][indices[d]]
                indices[d] += 1

        return result

